window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-378be9d8d160adb9"]={"versions": [{"id": "FIG-378be9d8d160adb9", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Funktionales Datenfluss- und Mapping-Diagramm (QoS / Prioritätsverarbeitung im Switching-Core).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Modul <code>EthSwt</code> (Ethernet Switch Driver, MCAL/Complex Driver) gemäß IEEE 802.1Q QoS-Architektur.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des zweistufigen Prioritätsmodells für den Frame-Forwarding-Pfad:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Ingress-Ebene:</em> Ermittlung der internen Priorität und Abbildung auf standardisierte Traffic Classes (TC 0..7).</li>\n<li><em>Egress-Ebene:</em> Deterministische Zuordnung der Traffic Classes zu hardwarebasierten Egress-Port-Warteschlangen (<code>Queue_0</code> bis <code>Queue_n</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ingress-Prioritätsquellen:</strong></li>\n<li><code>PCP</code> (<em>Priority Code Point</em>): 3-Bit-Feld aus dem IEEE 802.1Q VLAN-Tag des eingehenden Ethernet-Frames.</li>\n<li><code>Regenerated Priority</code>: Port-spezifisch neu evaluierte Priorität (z. B. über VLAN-Regeneration-Tabellen gemäß IEEE 802.1Q).</li>\n<li><code>IPV</code> (<em>Internal Priority Value</em> / <em>IP Precedence/DSCP</em>): Intern definierter Prioritätswert, abgeleitet aus L3/L4-Headern oder Switch-internen Port-Defaults.</li>\n<li><strong>Funktionsblöcke & Zwischenentitäten:</strong></li>\n<li><code>Determination of priority</code>: Hardware-/Treiber-Entscheidungslogik am Ingress-Port zur Auswahl/Berechnung der maßgeblichen Rahmenpriorität.</li>\n<li><code>Traffic class (TC) 0..7</code>: Interne, normalisierte Verkehrsklassen (Abstraktionsschicht zwischen Frame-Priorität und physischer Hardware-Queue; Kardinalität: 8 logische Klassen, $TC_0$ bis $TC_7$).</li>\n<li><strong>Egress-Entitäten & Mappings:</strong></li>\n<li><code>Egress Port</code>: Physischer Ausgangsport des Ethernet-Switches mit hardwareunterstützten Sende-Warteschlangen.</li>\n<li><code>TC_x maps to Queue_x</code>: Statische oder konfigurierbare $1:1$-Relation von der Traffic Class zur physikalischen Egress-Queue (<code>Queue_0</code> .. <code>Queue_7</code>).</li>\n<li><strong>AUTOSAR BSW-Konfigurationscontainer (ARXML):</strong></li>\n<li>Ingress: <code>EthSwtPortTrafficClassAssignment</code> bzw. <code>EthSwtPriorityTrafficClassAssignment</code>.</li>\n<li>Egress: <code>EthSwtTrafficClassQueueAssignment</code> (Zuordnung von TC zu Hardware-Queue).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Frame-Ingress & Header-Parsing:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Empfang des Ethernet-Frames am Ingress-Port; hardwareseitige Extraktion von PCP, DSCP/IPV oder Zuordnung der Default-Port-Priorität bei untagged Frames.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prioritätsbestimmung (<code>Determination of priority</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Hardwaredurchlauf im Switch-Forwarding-Prozess.</li>\n<li>Auswertung gemäß konfigurierter Ingress-Richtlinie (Priorisierung: PCP vs. IPV vs. Regenerated Priority).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Traffic-Class-Klassifizierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappen der ermittelten Frame-Priorität (Wertebereich 0..7) auf eine interne Traffic Class (TC 0..7) via Ingress-Port-Mapping-Tabelle.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Egress-Port-Queuing & Scheduling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Weiterleitungsentscheidung (FDB-Lookup): Adressierung des Zielports.</li>\n<li>Einreihen des Frames in die Egress-Queue <code>Queue_x</code>, die der jeweiligen <code>TC_x</code> zugewiesen ist.</li>\n<li>Abarbeitung der Queues durch den Egress-Scheduler (z. B. Strict Priority, Strict Priority + Weighted Round Robin, IEEE 802.1Qav CBS).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Hardware-Einschränkungen (Queue-Untermenge):</strong></li>\n<li>Bietet die Switch-Hardware weniger als 8 Egress-Queues (z. B. 4 Queues gemäß Tab. 7.4), schreibt AUTOSAR vor, dass zwingend eine aufsteigende, lückenlose Untermenge beginnend bei <code>TC 0</code> (<code>Queue 0</code>) verwendet werden muss. Höhere TCs müssen entsprechend gebündelt oder auf verfügbare Queues gefaltet werden.</li>\n<li><strong>Konfigurations-Constraints & Deprecations:</strong></li>\n<li><code>[SWS_EthSwt_00133]</code> ist als <strong>OBSOLETE</strong> markiert und durch <code>[SWS_EthSwt_CONSTR_00495]</code> ersetzt: Die Zuordnung von Ingress-Priorität zu TC erfolgt exklusiv entweder über <code>EthSwtPortTrafficClassAssignment</code> oder <code>EthSwtPriorityTrafficClassAssignment</code>. Eine redundante oder widersprüchliche Mischkonfiguration führt zu Validierungsfehlern im Generierungslauf.</li>\n<li><strong>Laufzeit- & Echtzeitaspekte (TSN/QoS):</strong></li>\n<li>Entwickler müssen sicherstellen, dass zeitkritische Frames (z. B. PTP/IEEE 802.1AS via <code>EthIf</code>/<code>EthTSyn</code> oder AVB/TSN-Streams) auf die höchste Traffic Class gemappt werden, die der höchsten prioritären Hardware-Queue zugeordnet ist, um Head-of-Line-Blocking und Jitter durch Bulk-Traffic (<code>TC 0</code>) zu verhindern.</li>\n</ul>"}, {"id": "FIG-0145db8eaf1f0312", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Funktionales Datenfluss- und Mapping-Diagramm (QoS / Prioritätsverarbeitung im Switching-Core).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Modul <code>EthSwt</code> (Ethernet Switch Driver, MCAL/Complex Driver) gemäß IEEE 802.1Q QoS-Architektur.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des zweistufigen Prioritätsmodells für den Frame-Forwarding-Pfad:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Ingress-Ebene:</em> Ermittlung der internen Priorität und Abbildung auf standardisierte Traffic Classes (TC 0..7).</li>\n<li><em>Egress-Ebene:</em> Deterministische Zuordnung der Traffic Classes zu hardwarebasierten Egress-Port-Warteschlangen (<code>Queue_0</code> bis <code>Queue_n</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ingress-Prioritätsquellen:</strong></li>\n<li><code>Regenerated Priority</code>: Port-spezifisch neu evaluierte Priorität (z. B. über VLAN-Regeneration-Tabellen gemäß IEEE 802.1Q).</li>\n<li><code>IPV</code> (<em>Internal Priority Value</em> / <em>IP Precedence/DSCP</em>): Intern definierter Prioritätswert, abgeleitet aus L3/L4-Headern oder Switch-internen Port-Defaults.</li>\n<li><strong>Funktionsblöcke & Zwischenentitäten:</strong></li>\n<li><code>Determination of priority</code>: Hardware-/Treiber-Entscheidungslogik am Ingress-Port zur Auswahl/Berechnung der maßgeblichen Rahmenpriorität.</li>\n<li><code>Traffic class (TC) 0..7</code>: Interne, normalisierte Verkehrsklassen (Abstraktionsschicht zwischen Frame-Priorität und physischer Hardware-Queue; Kardinalität: 8 logische Klassen, $TC_0$ bis $TC_7$).</li>\n<li><strong>Egress-Entitäten & Mappings:</strong></li>\n<li><code>Egress Port</code>: Physischer Ausgangsport des Ethernet-Switches mit hardwareunterstützten Sende-Warteschlangen.</li>\n<li><code>TC_x maps to Queue_x</code>: Statische oder konfigurierbare $1:1$-Relation von der Traffic Class zur physikalischen Egress-Queue (<code>Queue_0</code> .. <code>Queue_7</code>).</li>\n<li><strong>AUTOSAR BSW-Konfigurationscontainer (ARXML):</strong></li>\n<li>Ingress: <code>EthSwtPortTrafficClassAssignment</code> bzw. <code>EthSwtPriorityTrafficClassAssignment</code>.</li>\n<li>Egress: <code>EthSwtTrafficClassQueueAssignment</code> (Zuordnung von TC zu Hardware-Queue).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Frame-Ingress & Header-Parsing:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Empfang des Ethernet-Frames am Ingress-Port; hardwareseitige Extraktion von DSCP/IPV oder Zuordnung der Default-Port-Priorität bei untagged Frames.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prioritätsbestimmung (<code>Determination of priority</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Hardwaredurchlauf im Switch-Forwarding-Prozess.</li>\n<li>Auswertung gemäß konfigurierter Ingress-Richtlinie (Priorisierung: IPV vs. Regenerated Priority).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Traffic-Class-Klassifizierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappen der ermittelten Frame-Priorität (Wertebereich 0..7) auf eine interne Traffic Class (TC 0..7) via Ingress-Port-Mapping-Tabelle.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Egress-Port-Queuing & Scheduling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Weiterleitungsentscheidung (FDB-Lookup): Adressierung des Zielports.</li>\n<li>Einreihen des Frames in die Egress-Queue <code>Queue_x</code>, die der jeweiligen <code>TC_x</code> zugewiesen ist.</li>\n<li>Abarbeitung der Queues durch den Egress-Scheduler (z. B. Strict Priority, Strict Priority + Weighted Round Robin, IEEE 802.1Qav CBS).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Hardware-Einschränkungen (Queue-Untermenge):</strong></li>\n<li>Bietet die Switch-Hardware weniger als 8 Egress-Queues (z. B. 4 Queues gemäß Tab. 7.4), schreibt AUTOSAR vor, dass zwingend eine aufsteigende, lückenlose Untermenge beginnend bei <code>TC 0</code> (<code>Queue 0</code>) verwendet werden muss. Höhere TCs müssen entsprechend gebündelt oder auf verfügbare Queues gefaltet werden.</li>\n<li><strong>Konfigurations-Constraints & Deprecations:</strong></li>\n<li><code>[SWS_EthSwt_00133]</code> ist als <strong>OBSOLETE</strong> markiert und durch <code>[SWS_EthSwt_CONSTR_00495]</code> ersetzt: Die Zuordnung von Ingress-Priorität zu TC erfolgt exklusiv entweder über <code>EthSwtPortTrafficClassAssignment</code> oder <code>EthSwtPriorityTrafficClassAssignment</code>. Eine redundante oder widersprüchliche Mischkonfiguration führt zu Validierungsfehlern im Generierungslauf.</li>\n<li><strong>Laufzeit- & Echtzeitaspekte (TSN/QoS):</strong></li>\n<li>Entwickler müssen sicherstellen, dass zeitkritische Frames (z. B. PTP/IEEE 802.1AS via <code>EthIf</code>/<code>EthTSyn</code> oder AVB/TSN-Streams) auf die höchste Traffic Class gemappt werden, die der höchsten prioritären Hardware-Queue zugeordnet ist, um Head-of-Line-Blocking und Jitter durch Bulk-Traffic (<code>TC 0</code>) zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-378be9d8d160adb9", "to": "FIG-0145db8eaf1f0312", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Ingress-Prioritätsquellen / <code>PCP</code>:</strong> Das Eingangs-Element <code>PCP</code> (Priority Code Point) inklusive Verbindungspfeil zum Funktionsblock <code>Determination of priority</code> wurde entfernt; als Ingress-Eingangsgrößen verbleiben ausschließlich <code>IPV</code> und <code>Regenerated Priority</code>.</li>\n</ul>"}]};
